import io, json, sqlite3
from sync.client import VendorClient, http_get_json

with open('/tmp/catalog-before-sync.json') as f:
    before = {row[0]: tuple(row) for row in json.load(f)}
urls = []
def fetch(url):
    urls.append(url)
    return http_get_json(url)
records = list(VendorClient(fetch_json=fetch, notices=io.StringIO()).iter_items())
expected = before.copy()
for item in records:
    sku = item['sku']
    if sku in expected and expected[sku][3] == 'manual':
        continue
    if item.get('deleted'):
        expected.pop(sku, None)
    else:
        expected[sku] = (sku, item['name'], item['price_paise'], 'vendor', item.get('updated_at'))
with sqlite3.connect('data/catalog.db') as c:
    actual = {row[0]: row for row in c.execute('SELECT * FROM products')}
    assert c.execute('PRAGMA integrity_check').fetchone() == ('ok',)
    print('Sync state:', c.execute('SELECT * FROM sync_state').fetchall())
assert actual.keys() == expected.keys()
for sku, row in expected.items():
    assert actual[sku][:4] == row[:4], sku
    if row[4] is not None:
        assert actual[sku][4] == row[4], sku
manual = {sku: row for sku, row in before.items() if row[3] == 'manual'}
assert all(actual[sku] == row for sku, row in manual.items())
seen = {item['sku'] for item in records}
unmentioned = set(before) - seen
assert all(actual[sku] == before[sku] for sku in unmentioned)
print(f'Verified {len(records)} records across {len(urls)} pages; {len(actual)} catalogue rows match.')
print(f'Preserved all {len(manual)} manual SKUs and all {len(unmentioned)} unmentioned local SKUs.')
